// Turn yesterday's public GitHub events into short Markdown bullets.
const start = $now.minus({ days: 1 }).startOf('day');
const end = $now.startOf('day');
const items = $input.all().map((item) => item.json);

const MAX_REASON_LENGTH = 120;
const failed = items.find((json) => json.error);
if (failed) {
  const message = failed.error.message ?? String(failed.error);
  const reason = /rate limit/i.test(message)
    ? 'rate limit reached (60 requests an hour per IP without a token)'
    : message.split('\n')[0].slice(0, MAX_REASON_LENGTH);
  return [{ json: { ok: false, count: 0, markdown: `- Could not reach GitHub: ${reason}` } }];
}

const pr = (p) => p?.pull_request ?? {};
const issue = (p) => p?.issue ?? {};
const titled = (prefix, number, title) => `${prefix} #${number}${title ? ` "${title}"` : ''}`;
const cap = (word) => {
  const text = String(word || 'updated');
  return `${text[0].toUpperCase()}${text.slice(1)}`;
};

function describe({ type, repo, payload: rawPayload }) {
  const payload = rawPayload ?? {};
  const where = repo?.name ?? 'a repo';
  switch (type) {
    case 'PushEvent':
      return `Pushed to ${where}`;
    case 'PullRequestEvent': {
      const action = payload.action === 'closed' && pr(payload).merged ? 'merged' : payload.action;
      return `${cap(action)} ${titled('PR', payload.number ?? pr(payload).number, pr(payload).title)} in ${where}`;
    }
    case 'PullRequestReviewEvent':
      return `Reviewed ${titled('PR', pr(payload).number, pr(payload).title)} in ${where}`;
    case 'PullRequestReviewCommentEvent':
      return `Commented on a review in ${titled('PR', pr(payload).number, pr(payload).title)} in ${where}`;
    case 'IssuesEvent':
      return `${cap(payload.action)} ${titled('issue', issue(payload).number, issue(payload).title)} in ${where}`;
    case 'IssueCommentEvent':
      return `Commented on ${issue(payload).pull_request ? 'PR' : 'issue'} ${titled('', issue(payload).number, issue(payload).title).trim()} in ${where}`;
    case 'CreateEvent':
      return payload.ref_type === 'repository' ? `Created repo ${where}` : `Created ${payload.ref_type} ${payload.ref} in ${where}`;
    case 'ForkEvent':
      return `Forked ${where}`;
    case 'WatchEvent':
      return `Starred ${where}`;
    case 'ReleaseEvent':
      return `Published release ${payload.release?.tag_name ?? ''} in ${where}`.replace('  ', ' ');
    default:
      return `${type.replace(/Event$/, '')} in ${where}`;
  }
}

const lines = items
  .filter((json) => json.type && json.created_at)
  .filter((json) => {
    const at = DateTime.fromISO(json.created_at);
    return at >= start && at < end;
  })
  .reverse()
  .map(describe);

const counts = new Map();
for (const line of lines) counts.set(line, (counts.get(line) ?? 0) + 1);
const bullets = [...counts].map(([line, n]) => `- ${line}${n > 1 ? ` (x${n})` : ''}`);

return [{
  json: {
    ok: true,
    count: lines.length,
    markdown: bullets.join('\n') || '- No public activity',
  },
}];
